"""Generate the agent-facing block in AGENTS.md (and other agent files) from the constitution."""
from __future__ import annotations

from pathlib import Path

from .config import Config

BEGIN = "<!-- iwos:begin -->"
END = "<!-- iwos:end -->"


def render(cfg: Config) -> str:
    protected = "\n".join(f"- `{p}`" for p in cfg.protected) or "- (none declared)"
    architecture = "\n".join(f"- `{p}`" for p in cfg.architecture) or "- (none declared)"
    return f"""{BEGIN}
## Constitution (generated by `iwos agents`; do not edit by hand)

This repository is governed by IWOS Guard. Before you change a file, ask for authority: run
`iwos mcp` as a Model Context Protocol server and call `check_authority` with the path, or read
the rules below. A change that breaks them fails the `iwos gate` check on the pull request.

**Protected artefacts.** You must not modify these without an accepted proposal cited in the pull
request or commit message (pattern `{cfg.proposal_pattern}`), and the lock `{cfg.lock_file}` must be
regenerated with `iwos lock` in the same change:
{protected}

**Architecture.** Changes under these paths must cite a decision record (pattern `{cfg.decision_pattern}`):
{architecture}

**Traceability.** Every pull request must cite the artefact that authorises it (one of
{", ".join(f"`{p}`" for p in cfg.traceability_patterns)}).{"" if cfg.traceability_required else " (advisory)"}

**Decisions.** Record a decision that constrains future work with the `record_decision` tool or by
appending to `{cfg.decision_ledger}`. Never edit or delete an existing entry.

**Verify.** Run `iwos validate` before and after your change. If the integrity check fails before you
start, stop and report: a protected artefact and the lock disagree, and you must not regenerate the lock
to make it pass.
{END}"""


def apply(cfg: Config, path: Path) -> bool:
    """Insert or replace the block. Returns True when the file changed."""
    block = render(cfg)
    if path.exists():
        text = path.read_text(encoding="utf-8")
        if BEGIN in text and END in text:
            start, end = text.index(BEGIN), text.index(END) + len(END)
            new = text[:start] + block + text[end:]
        else:
            new = text.rstrip("\n") + "\n\n" + block + "\n"
    else:
        new = f"# Agent Operating Guide\n\n{block}\n"
    if path.exists() and path.read_text(encoding="utf-8") == new:
        return False
    path.write_text(new, encoding="utf-8")
    return True


def is_fresh(cfg: Config, path: Path) -> bool:
    if not path.exists():
        return False
    text = path.read_text(encoding="utf-8")
    if BEGIN not in text or END not in text:
        return False
    return text[text.index(BEGIN): text.index(END) + len(END)] == render(cfg)


def stale_files(cfg: Config) -> list[str]:
    return [f for f in cfg.agent_files if not is_fresh(cfg, cfg.root / f)]
